import argparse,ast,base64,re,shutil
from pathlib import Path
from datetime import datetime
PAYLOAD={'cliente_github_0421.py': '', 'patch_core.py': '', 'aplicar_patch.py': '', 'release_github.py': ''}
DEFAULT_REPO='rumenignascimento/aoe2-companion-updates'

def painel(source):
    tree=ast.parse(source)
    if any(isinstance(n,ast.ImportFrom) and n.module=='cliente_github_0421' for n in tree.body):return source
    index=next((i for i,n in enumerate(tree.body) if isinstance(n,ast.If) and '__name__' in ast.unparse(n.test)),None)
    if index is None or not any(isinstance(n,ast.ClassDef) and n.name=='Window' for n in tree.body):raise ValueError('Módulo de jogadores não reconhecido.')
    tree.body[index:index]=ast.parse('from cliente_github_0421 import ativar as _ativar_github_0421\n_ativar_github_0421(globals())').body
    ast.fix_missing_locations(tree);return ast.unparse(tree)+'\n'

def instalador(source):
    tree=ast.parse(source);found=False
    for node in ast.walk(tree):
        if isinstance(node,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='arquivos' for t in node.targets) and isinstance(node.value,ast.List):
            values=[getattr(n,'value',None) for n in node.value.elts]
            if 'painel_jogadores.py' in values:
                found=True
                for name in ('cliente_github_0421.py','patch_core.py'):
                    if name not in values:node.value.elts.append(ast.Constant(value=name))
    if not found:raise ValueError('Lista de módulos do instalador não reconhecida.')
    ast.fix_missing_locations(tree);return ast.unparse(tree)+'\n'

def main():
    parser=argparse.ArgumentParser(description='Integra o canal público do GitHub; não faz upload.')
    parser.add_argument('--repo',default=DEFAULT_REPO);args=parser.parse_args()
    repo=args.repo.strip().removeprefix('https://github.com/').rstrip('/').removesuffix('.git')
    if not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9-]{0,38}/[A-Za-z0-9_.-]+',repo):raise ValueError('Use usuario/repositorio ou URL do GitHub.')
    root=Path(__file__).resolve().parent;result={}
    for name,adapt in [('painel_jogadores.py',painel),('gerar_instalador.py',instalador)]:
        path=root/name
        if not path.is_file():raise ValueError('Arquivo ausente: '+name+'. Salve este configurador em GeradorMapaAoE2.')
        result[name]=adapt(path.read_text(encoding='utf-8-sig'))
    for name,b64 in PAYLOAD.items():
        code=base64.b64decode(b64).decode('utf-8')
        if name=='cliente_github_0421.py':code=code.replace('REPOSITORY='+repr(DEFAULT_REPO),'REPOSITORY='+repr(repo))
        if name=='release_github.py':code=code.replace('DEFAULT_REPO='+repr(DEFAULT_REPO),'DEFAULT_REPO='+repr(repo))
        result[name]=code
    for name,code in result.items():compile(code,name,'exec')
    backup=root/'backups_atualizacoes'/datetime.now().strftime('%Y%m%d-%H%M%S-%f');backup.mkdir(parents=True)
    existed={n:(root/n).is_file() for n in result}
    for n in result:
        if existed[n]:shutil.copy2(root/n,backup/n)
    try:
        for n,code in result.items():
            temp=root/(n+'.tmp');temp.write_text(code,encoding='utf-8');temp.replace(root/n)
    except Exception:
        for n in result:
            if existed[n]:shutil.copy2(backup/n,root/n)
            else:(root/n).unlink(missing_ok=True)
        raise
    print('Canal configurado:',repo,'| Backup:',backup)
    print('Nada foi publicado. Gere o próximo patch com py -3.12 gerar_patch.py.')
    print('Depois: py -3.12 release_github.py. Revise a pasta publicacao_github antes de enviar ao GitHub.')
if __name__=='__main__':
    try:main()
    except Exception as e:print('ERRO:',e);raise SystemExit(1)
